using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class GeneratedFormatterForReferencedTypeTests
{
    private static async Task<List<MetadataReference>> FrameworkReferencesAsync()
    {
        ImmutableArray<MetadataReference> framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        return framework.ToList();
    }

    private static async Task<MetadataReference> CompileProjectAAsync(string source)
    {
        List<MetadataReference> refs = await FrameworkReferencesAsync();
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ProjectA",
            new[] { CSharpSyntaxTree.ParseText(source, new CSharpParseOptions(LanguageVersion.CSharp12)) },
            refs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        using MemoryStream ms = new();
        var emit = compilation.Emit(ms);
        Assert.True(emit.Success, string.Join(Environment.NewLine, emit.Diagnostics));
        return MetadataReference.CreateFromImage(ms.ToArray());
    }

    private static async Task<(Compilation Output, GeneratorDriverRunResult Run)> RunProjectBAsync(MetadataReference projectA, string source)
    {
        List<MetadataReference> refs = await FrameworkReferencesAsync();
        refs.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
        refs.Add(projectA);
        CSharpParseOptions parseOptions = new(LanguageVersion.CSharp12);
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ProjectB",
            new[] { CSharpSyntaxTree.ParseText(source, parseOptions) },
            refs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new[] { new global::MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out ImmutableArray<Diagnostic> _);
        return (output, driver.GetRunResult());
    }

    [Fact]
    public async Task BodylessFormatterForTypeInAssemblyWithoutMessagePackIsGenerated()
    {
        MetadataReference projectA = await CompileProjectAAsync("""
            namespace ProjectA
            {
                public class MyType
                {
                    public int Id { get; set; }
                    public string Name { get; set; }
                }
            }
            """);

        (Compilation output, GeneratorDriverRunResult run) = await RunProjectBAsync(projectA, """
            using MessagePack;
            using MessagePack.Formatters;

            namespace ProjectB
            {
                [GeneratedMessagePackResolver]
                partial class MyResolver { }

                [GeneratedMessagePackFormatter]
                partial class MyTypeFormatter : IMessagePackFormatter<ProjectA.MyType>;
            }
            """);

        Assert.All(run.Results, r => Assert.Null(r.Exception));
        Assert.Empty(run.Diagnostics.Where(d => d.Severity == DiagnosticSeverity.Error));
        Assert.Empty(output.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error));
        Assert.Contains(run.GeneratedTrees, t => t.ToString().Contains("MyTypeFormatter") && t.ToString().Contains("Serialize("));
    }

    [Fact]
    public async Task ContractlessFormatterIncludesPublicMembersOfUnannotatedType()
    {
        MetadataReference projectA = await CompileProjectAAsync("""
            namespace ProjectA
            {
                public class Plain
                {
                    public int UniqueIdMember { get; set; }
                    public string UniqueLabelMember { get; set; }
                }
            }
            """);

        (Compilation output, GeneratorDriverRunResult run) = await RunProjectBAsync(projectA, """
            using MessagePack;
            using MessagePack.Formatters;

            namespace ProjectB
            {
                [GeneratedMessagePackResolver]
                partial class MyResolver { }

                [GeneratedMessagePackFormatter]
                public partial class PlainFormatter : IMessagePackFormatter<ProjectA.Plain>
                {
                }
            }
            """);

        Assert.All(run.Results, r => Assert.Null(r.Exception));
        Assert.Empty(output.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error));
        string formatterText = string.Join("\n", run.GeneratedTrees.Select(t => t.ToString()).Where(t => t.Contains("PlainFormatter") && t.Contains("Serialize(")));
        Assert.Contains("UniqueIdMember", formatterText);
        Assert.Contains("UniqueLabelMember", formatterText);
    }
}

