using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Testing;

namespace Receipts.GeneratedTests;

public class GeneratedFormatterHonoursAttributesTests
{
    private static async Task<List<MetadataReference>> ReferencesAsync(bool withMessagePack)
    {
        ImmutableArray<MetadataReference> framework = await ReferenceAssemblies.Net.Net80.ResolveAsync(LanguageNames.CSharp, CancellationToken.None);
        List<MetadataReference> refs = framework.ToList();
        if (withMessagePack)
        {
            refs.AddRange(ReferencesHelper.GetReferences(ReferencesSet.MessagePack));
        }

        return refs;
    }

    private static async Task<MetadataReference> CompileProjectAAsync(string source, bool withMessagePack)
    {
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ProjectA",
            new[] { CSharpSyntaxTree.ParseText(source, new CSharpParseOptions(LanguageVersion.CSharp12)) },
            await ReferencesAsync(withMessagePack),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        using MemoryStream ms = new();
        var emit = compilation.Emit(ms);
        Assert.True(emit.Success, string.Join(Environment.NewLine, emit.Diagnostics));
        return MetadataReference.CreateFromImage(ms.ToArray());
    }

    private static async Task<string> GenerateFormatterTextAsync(MetadataReference projectA, string source, string formatterName)
    {
        List<MetadataReference> refs = await ReferencesAsync(withMessagePack: true);
        refs.Add(projectA);
        CSharpParseOptions parseOptions = new(LanguageVersion.CSharp12);
        CSharpCompilation compilation = CSharpCompilation.Create(
            "ProjectB",
            new[] { CSharpSyntaxTree.ParseText(source, parseOptions) },
            refs,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            new[] { new global::MessagePack.SourceGenerator.MessagePackGenerator().AsSourceGenerator() },
            parseOptions: parseOptions);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out ImmutableArray<Diagnostic> _);
        GeneratorDriverRunResult run = driver.GetRunResult();
        Assert.All(run.Results, r => Assert.Null(r.Exception));
        Assert.Empty(output.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error));
        string text = string.Join("\n", run.GeneratedTrees.Select(t => t.ToString()).Where(t => t.Contains(formatterName) && t.Contains("Serialize(")));
        Assert.False(string.IsNullOrEmpty(text), "No generated formatter body found.");
        return text;
    }

    [Fact]
    public async Task HonoursMessagePackObjectAttributesOnFormattedType()
    {
        MetadataReference projectA = await CompileProjectAAsync("""
            using MessagePack;

            namespace ProjectA
            {
                [MessagePackObject]
                public class Keyed
                {
                    [Key(0)]
                    public int Id { get; set; }

                    [IgnoreMember]
                    public string IgnoredSecretMember { get; set; }
                }
            }
            """, withMessagePack: true);

        string text = await GenerateFormatterTextAsync(projectA, """
            using MessagePack;
            using MessagePack.Formatters;

            namespace ProjectB
            {
                [GeneratedMessagePackResolver]
                partial class MyResolver { }

                [GeneratedMessagePackFormatter]
                partial class KeyedFormatter : IMessagePackFormatter<ProjectA.Keyed>;
            }
            """, "KeyedFormatter");

        Assert.DoesNotContain("IgnoredSecretMember", text);
    }

    [Fact]
    public async Task HonoursDataContractOnFormattedType()
    {
        MetadataReference projectA = await CompileProjectAAsync("""
            using System.Runtime.Serialization;

            namespace ProjectA
            {
                [DataContract]
                public class Dc
                {
                    [DataMember(Order = 0)]
                    public int Id { get; set; }

                    public string NotADataMemberValue { get; set; }
                }
            }
            """, withMessagePack: false);

        string text = await GenerateFormatterTextAsync(projectA, """
            using MessagePack;
            using MessagePack.Formatters;

            namespace ProjectB
            {
                [GeneratedMessagePackResolver]
                partial class MyResolver { }

                [GeneratedMessagePackFormatter]
                partial class DcFormatter : IMessagePackFormatter<ProjectA.Dc>;
            }
            """, "DcFormatter");

        Assert.DoesNotContain("NotADataMemberValue", text);
    }
}
